{
  "originalFormula": "V_{total} = |\phi_{n}| + |\phi_{p}| + V_{R}",
  "genericFormula": "V_{total} = |\phi_{n}| + |\phi_{p}| + V_{R}",
  "description": "Esta fórmula representa a tensão total em um circuito que envolve a soma das tensões de dois potenciais elétricos, um associado a portadores de carga negativa e outro a portadores de carga positiva, além de uma tensão adicional que pode ser de um resistor ou outra fonte.",
  "concepts": [
    "Potencial elétrico",
    "Tensão em circuitos elétricos",
    "Portadores de carga em semicondutores",
    "Resistência elétrica"
  ],
  "symbols": [
    {
      "symbol": "V_{total}",
      "description": "Representa a tensão total do circuito, que é a soma das tensões individuais."
    },
    {
      "symbol": "|\phi_{n}|",
      "description": "Representa o valor absoluto do potencial elétrico associado a portadores de carga negativa, como elétrons."
    },
    {
      "symbol": "|\phi_{p}|",
      "description": "Representa o valor absoluto do potencial elétrico associado a portadores de carga positiva, como lacunas em um semicondutor."
    },
    {
      "symbol": "V_{R}",
      "description": "Representa a tensão em um resistor ou outra fonte de tensão no circuito."
    }
  ]
}
